"""Summarize text with a local Hugging Face sequence-to-sequence model."""


def summarize(text: str, min_length: int = 5, max_length: int = 40) -> str:
    """Return a deterministic summary generated by BART."""
    from transformers import AutoModelForSeq2SeqLM, AutoTokenizer

    model_id = "facebook/bart-large-cnn"
    tokenizer = AutoTokenizer.from_pretrained(model_id)
    model = AutoModelForSeq2SeqLM.from_pretrained(model_id)
    inputs = tokenizer(text, return_tensors="pt", truncation=True, max_length=1024)
    output = model.generate(
        **inputs,
        max_length=max_length,
        min_length=min_length,
        do_sample=False,
    )
    return tokenizer.decode(output[0], skip_special_tokens=True)


def main() -> None:
    article = (
        "A university launched a new AI laboratory focused on practical "
        "applications, responsible evaluation, and student research."
    )
    print(summarize(article))


if __name__ == "__main__":
    main()
